/* Loaded only by the service worker. Personal API responses are never cached. */
const OFFLINE_INDEX_CACHE='proplet-offline-index-v1';
const OFFLINE_ASSET_CACHE='proplet-offline-assets-v1';
let offlineAssetsJob=null;

async function activeOfflineResponse(path){
 try{
  const index=await (await caches.open(OFFLINE_INDEX_CACHE)).match('/__proplet-offline__/active');
  if(!index?.ok)return null;
  const active=await index.json();
  if(!String(active.cacheName||'').startsWith('proplet-offline-content-v1-'))return null;
  return (await caches.open(active.cacheName)).match(path);
 }catch{return null}
}

async function ensureOfflineAssets(){
 if(offlineAssetsJob)return offlineAssetsJob;
 offlineAssetsJob=(async()=>{
  const shell=await caches.open(SHELL_CACHE);
  const manifestResponse=await shell.match('/offline-assets.json');
  if(!manifestResponse?.ok)throw Error('offline-assets-manifest-missing');
  const manifest=await manifestResponse.json();
  if(manifest.schemaVersion!==1||!Array.isArray(manifest.assets)||manifest.assets.length>300)throw Error('offline-assets-manifest-invalid');
  const cache=await caches.open(OFFLINE_ASSET_CACHE);
  let cursor=0;
  await Promise.all(Array.from({length:5},async()=>{
   while(cursor<manifest.assets.length){
    const path=manifest.assets[cursor++],url=new URL(path,self.location.origin);
    if(url.origin!==self.location.origin||!path.startsWith('/')||url.pathname.startsWith('/api/'))throw Error('offline-asset-invalid');
    if((await cache.match(path))?.ok||(await shell.match(path))?.ok)continue;
    const response=await fetch(path,{cache:'no-cache'});
    if(!response.ok)throw Error('offline-asset-download-failed');
    await cache.put(path,response);
   }
  }));
  // Ready refers to the current release's complete shell, never an older worker.
  for(const path of SHELL)if(!(await shell.match(path))?.ok)throw Error('offline-shell-incomplete');
  return {ready:true,shell:SHELL_CACHE};
 })().finally(()=>{offlineAssetsJob=null});
 return offlineAssetsJob;
}

self.addEventListener('message',event=>{
 if(event.data?.type!=='GET_OFFLINE_STATUS')return;
 event.waitUntil(ensureOfflineAssets().then(value=>event.ports?.[0]?.postMessage(value)).catch(()=>event.ports?.[0]?.postMessage({ready:false})));
});


async function putIfOk(cacheName,request,response){
  if(!response?.ok)return response;
  const cache=await caches.open(cacheName);
  await cache.put(request,response.clone());
  return response;
}

async function precacheShell(){
  const cache=await caches.open(SHELL_CACHE);
  const results=await Promise.allSettled([...new Set(SHELL)].map(async path=>{
    // Every listed shell asset is required. Reject installation on any failure
    // so the previous worker and its complete offline cache remain active.
    const response=await fetch(path,{cache:'no-store'});
    if(!response.ok)throw new Error(`shell-precache-${response.status}: ${path}`);
    await cache.put(path,response);
  }));
  const failed=results.find(result=>result.status==='rejected');
  if(failed){
    // Wait for every writer before deleting this candidate; late writes must
    // not recreate a partial shell. Never touch the previous release here.
    await caches.delete(SHELL_CACHE);
    throw failed.reason;
  }
}

async function preserveExistingPuzzleDatabase(){
  try{
    const existing=await caches.match('/puzzles.json',{ignoreSearch:true});
    if(existing?.ok){const data=await existing.clone().json();if(Number(data?.contentGeneration)===4&&Number(data?.dailyGeneration)===4&&data?.datedDaily?.cutover==='2026-10-08')await (await caches.open(DATA_CACHE)).put('/puzzles.json',existing.clone())}
  }catch{}
}

self.addEventListener('install',e=>{
  e.waitUntil(Promise.all([precacheShell(),preserveExistingPuzzleDatabase()]).then(()=>self.skipWaiting()));
});
self.addEventListener('message',e=>{if(e.data?.type==='SKIP_WAITING')self.skipWaiting()});
self.addEventListener('activate',e=>e.waitUntil((async()=>{
  const keep=new Set([SHELL_CACHE,DATA_CACHE]);
  await caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(CACHE_PREFIX)&&!keep.has(k)&&!k.startsWith('proplet-offline-')).map(k=>caches.delete(k))));
  await self.clients.claim();
  const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});
  // Activation must not reboot a game or discard its in-memory/local state.
  // Each page applies the update automatically when its own game and
  // dialogs are closed; background/offline pages wait until they return.
  clients.forEach(client=>client.postMessage({type:'PROPLET_SW_UPDATED',shell:SHELL_CACHE}));
})()));

async function networkFirst(request,cacheName,fallback){
  try{return await putIfOk(cacheName,request,await fetch(request))}
  catch{
    const offline=new URL(request.url).pathname==='/puzzles.json'?await activeOfflineResponse('/puzzles.json'):null;
    if(offline)return offline;
    const cached=await caches.match(request,{ignoreSearch:request.mode==='navigate'});
    if(cached)return cached;
    if(fallback)return (await caches.match(fallback))||Response.error();
    return Response.error();
  }
}

async function cacheFirst(request){
  const cached=await caches.match(request);
  if(cached)return cached;
  const url=new URL(request.url);
  if(/\.(svg|webp|png|woff2?|ttf|txt)$/.test(url.pathname)){const offline=await (await caches.open(OFFLINE_ASSET_CACHE)).match(url.pathname)||await caches.match(url.pathname);if(offline)return offline}
  return putIfOk(SHELL_CACHE,request,await fetch(request));
}

async function staleWhileRevalidate(event){
  const cached=await caches.match(event.request);
  const refresh=fetch(event.request,{cache:'no-store'}).then(r=>putIfOk(DATA_CACHE,event.request,r));
  if(cached){event.waitUntil(refresh.catch(()=>{}));return cached}
  return refresh;
}

self.addEventListener('fetch',e=>{
  if(e.request.method!=='GET')return;
  const u=new URL(e.request.url);
  if(u.origin!==self.location.origin)return;
  if(u.pathname.startsWith('/_vercel/'))return;
  // Administration is an online-only, separately authenticated workspace.
  // Never serve its shell/modules from a gameplay cache or fall back to '/'.
  if(/^\/admin(?:\/|\.|$)/.test(u.pathname))return;
  if(u.pathname==='/api/rolling-content'){
    // A package manifest can announce a new release within the same week.
    // Never bind yesterday's cached delta to that fresh manifest. The app
    // already reads its previous cached delta before requesting an update.
    if(e.request.cache==='no-store'){
      e.respondWith(fetch(e.request).then(r=>putIfOk(DATA_CACHE,e.request,r)));
      return;
    }
    e.respondWith(staleWhileRevalidate(e).catch(async()=>await caches.match(e.request)||Response.error()));
    return;
  }
  if(u.pathname==='/puzzles.json'){
    e.respondWith(networkFirst(e.request,DATA_CACHE));
    return;
  }
  if(u.pathname.startsWith('/api/'))return;
  if(e.request.mode==='navigate'){
    e.respondWith(networkFirst(e.request,SHELL_CACHE,'/'));
    return;
  }
  e.respondWith(cacheFirst(e.request).catch(async()=>await caches.match(e.request)||Response.error()));
});

self.addEventListener('push',event=>{
  let data={};
  try{data=event.data?.json?.()||{}}catch{try{data={body:event.data?.text?.()||''}}catch{}}
  const title=data.title||'☀️ Nový Proplet je tady';
  const options={
    body:data.body||'Dnešní výzva čeká.',
    icon:'/icon.svg',
    badge:'/icon.svg',
    tag:data.tag||'proplet-daily',
    renotify:false,
    data:{url:data.url||'/?open=daily',deliveryId:data.deliveryId||null}
  };
  event.waitUntil(self.registration.showNotification(title,options));
});

self.addEventListener('notificationclick',event=>{
  event.notification.close();
  const target=new URL(event.notification.data?.url||'/?open=daily',self.location.origin).href;
  const deliveryId=event.notification.data?.deliveryId;
  const trackOpen=deliveryId
    ?fetch(`https://hrajproplet.cz/api/push/open?delivery_id=${encodeURIComponent(deliveryId)}`,{method:'POST',mode:'no-cors',keepalive:true}).catch(()=>null)
    :Promise.resolve(null);
  const openTarget=(async()=>{
    const clientsList=await self.clients.matchAll({type:'window',includeUncontrolled:true});
    for(const client of clientsList){
      try{
        let targetClient=client;
        if('navigate' in client){
          const navigatedClient=await client.navigate(target);
          if(!navigatedClient)continue;
          targetClient=navigatedClient;
        }
        if('focus' in targetClient){
          const focusedClient=await targetClient.focus();
          if(focusedClient)return focusedClient;
        }
      }catch{}
    }
    return self.clients.openWindow(target);
  })();
  event.waitUntil(Promise.all([trackOpen,openTarget]));
});








